-- One-time May 2026 NHIS monthly beneficiary replacement generated from HMO_10_RONSBERGER NIGERIA LTD._235.pdf.
BEGIN;
CREATE TEMP TABLE _nhis_import_run(id uuid) ON COMMIT DROP;
DELETE FROM public.nhis_beneficiaries;
WITH imported AS (SELECT id FROM _nhis_import_run) UPDATE public.nhis_update_runs u SET previous_record_count = (SELECT count(*) FROM public.nhis_beneficiaries_backup b WHERE b.run_id = u.id), new_record_count = (SELECT count(*) FROM public.nhis_beneficiaries), records_added = (SELECT count(*) FROM public.nhis_beneficiaries), records_removed = (SELECT count(*) FROM public.nhis_beneficiaries_backup b WHERE b.run_id = u.id), updated_at = now() WHERE u.id = (SELECT id FROM imported);
COMMIT;